begin;
create function pg_temp.assert_ok(ok boolean, message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception '%', message; end if; end $$;
create function pg_temp.expect_error(statement text) returns void language plpgsql as $$ begin begin execute statement; exception when others then return; end; raise exception 'Expected rejection: %', statement; end $$;
insert into auth.users(id) values ('00000000-0000-4000-8000-000000000081'), ('00000000-0000-4000-8000-000000000082');
update public.profiles set active=true where id in ('00000000-0000-4000-8000-000000000081','00000000-0000-4000-8000-000000000082');
insert into public.events(id,tba_key,year,name,game_slug,created_by) values ('10000000-0000-4000-8000-000000000081','2026media',2026,'Media test','2026-rebuilt','00000000-0000-4000-8000-000000000081');
insert into public.teams(team_number,tba_team_key) values (81,'frc81');
insert into public.event_teams(event_id,team_number) values ('10000000-0000-4000-8000-000000000081',81);
insert into public.robot_media(id,event_id,team_number,storage_path,uploaded_by,source) values ('20000000-0000-4000-8000-000000000081','10000000-0000-4000-8000-000000000081',81,'10000000-0000-4000-8000-000000000081/81/20000000-0000-4000-8000-000000000081.jpg','00000000-0000-4000-8000-000000000081','pit_upload');
insert into storage.objects(bucket_id,name) values ('robot-media','10000000-0000-4000-8000-000000000081/81/20000000-0000-4000-8000-000000000081.jpg');
select pg_temp.expect_error($s$insert into public.robot_media(event_id,team_number,storage_path,uploaded_by,source) values ('10000000-0000-4000-8000-000000000081',81,'bad-path','00000000-0000-4000-8000-000000000081','pit_upload')$s$);
select pg_temp.expect_error($s$insert into public.robot_media(event_id,team_number,external_url,source) values ('10000000-0000-4000-8000-000000000081',81,'https://evil.example/p.jpg','tba')$s$);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000082',true);
select pg_temp.assert_ok((select count(*)=1 from public.robot_media),'Active scout reads visible event photos');
select pg_temp.assert_ok((select count(*)=1 from storage.objects where bucket_id='robot-media'),'Active scout reads linked object metadata');
select pg_temp.expect_error($s$insert into storage.objects(bucket_id,name) values ('robot-media','arbitrary.jpg')$s$);
delete from storage.objects where bucket_id='robot-media';
select pg_temp.assert_ok((select count(*)=1 from storage.objects where bucket_id='robot-media'),'Scout cannot delete storage objects');
select pg_temp.expect_error($s$delete from public.robot_media$s$);
reset role;
update public.profiles set active=false where id='00000000-0000-4000-8000-000000000082';
set local role authenticated;
select pg_temp.assert_ok((select count(*)=0 from public.robot_media),'Inactive scout cannot read metadata');
select pg_temp.assert_ok((select count(*)=0 from storage.objects where bucket_id='robot-media'),'Inactive scout cannot read object metadata');
rollback;
